def dengi(z):
    try:
        n = int(float(z or 0))
    except Exception:
        n = 0
    return "{:,}".format(n).replace(",", " ") + " $" if n > 0 else ""


def nomer(m):
    return (m.get("auto_number") or "").strip()


def nazvanie(m):
    return " ".join(str(x) for x in (m.get("brand"), m.get("model"),
                                     m.get("year")) if x)


def etap(m):
    s = (m.get("status") or "").lower()
    if s.startswith("ua_"):
        return 4
    if s.startswith("ge_"):
        return 3
    if s.startswith("sea_"):
        return 2
    return 1


